add(new THREE.BoxGeometry(1.66,.08,.28),paint,0,1.02,.91);add(new THREE.BoxGeometry(1.7,.08,.25),paint,0,1.02,-1.22);
add(new THREE.BoxGeometry(2.18,.13,.26),dark,0,.52,-1.82);add(new THREE.BoxGeometry(2.15,.12,.32),dark,0,.49,2.02);
for(const x of [-.67,.67]){add(new THREE.BoxGeometry(.4,.1,.56),mat(0xfff0cc,.3),x,.72,2.05,false);add(new THREE.BoxGeometry(.4,.1,.28),mat(0xff413d,.3),x,.72,-2.05,false);}
