for(const side of [-1,1]){const everts=[];for(let i=0;i<samples.length;i++){const p=samples[i],t=curve.getTangentAt(i/(samples.length-1)),s=new THREE.Vector3(-t.z,0,t.x).normalize();const q=p.clone().addScaledVector(s,side*(width/2-.16));everts.push(q)}const eg=new THREE.BufferGeometry().setFromPoints(everts);const em=new THREE.Line(eg,edgeMat);em.position.y=.012;scene.add(em)}return curve}
