// Coastal town, palms, pines and roadside details give the island a sense of scale.
let seed=712;const rand=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};
const buildings=[];const buildingMats=[0xb8a78d,0xc3b9a2,0x82959a,0xd1c2a8,0x7d8888].map(c=>mat(c,.85));
